'use strict';

// MODULES //

import acoshf from '@stdlib/math-base-special-acoshf';
import f32 from '@stdlib/number-float64-base-to-float32';


// VARIABLES //

var ONE = f32( 1.0 );


// MAIN //

/**
* Computes the hyperbolic arcsecant of a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} hyperbolic arcsecant
*
* @example
* var v = asechf( 1.0 );
* // returns 0.0
*
* @example
* var v = asechf( 0.5 );
* // returns ~1.317
*
* @example
* var v = asechf( NaN );
* // returns NaN
*/
function asechf( x ) {
	return acoshf( f32( ONE / f32( x ) ) );
}


// EXPORTS //

export default asechf;
